var RC_ITEMS=['wolf','goat','cabbage'];
function rcSafe(left, right){ function bad(bank){ var has={}; bank.forEach(function(it){has[it]=1;}); if(has.wolf&&has.goat&&!has.farmer) return true; if(has.goat&&has.cabbage&&!has.farmer) return true; return false; } return !bad(left) && !bad(right); }
function rcStart(){ return {left:['farmer','wolf','goat','cabbage'], right:[], boat:'left'}; }
function rcMoves(st){ var here = st.boat==='left'? st.left : st.right; var res=[{take:null}]; var others=here.filter(function(x){return x!=='farmer';}); others.forEach(function(it){ res.push({take:it}); }); return res; }
function rcApply(st, mv){ var from = st.boat==='left'? 'left':'right'; var to = st.boat==='left'? 'right':'left'; var ns={left:st.left.slice(), right:st.right.slice(), boat:to}; function move(arr, item){ var i=arr.indexOf(item); if(i>=0) arr.splice(i,1); } move(ns[from],'farmer'); if(mv.take) move(ns[from], mv.take); ns[to].push('farmer'); if(mv.take) ns[to].push(mv.take); return ns; }
function rcGoal(st){ return st.right.length===4; }
function rcKey(st){ return st.left.slice().sort().join(',')+'|'+st.right.slice().sort().join(',')+'|'+st.boat; }
function rcSolve(){ var start=rcStart(); if(rcGoal(start)) return [start]; var q=[{st:start, path:[start]}]; var seen={}; seen[rcKey(start)]=1; while(q.length){ var cur=q.shift(); var moves=rcMoves(cur.st); for(var i=0;i<moves.length;i++){ var ns=rcApply(cur.st, moves[i]); if(!rcSafe(ns.left,ns.right)) continue; var key=rcKey(ns); if(seen[key]) continue; seen[key]=1; var np=cur.path.slice(); np.push(ns); if(rcGoal(ns)) return np; q.push({st:ns, path:np}); } } return null; }
var EXPORTS={rcStart:rcStart,rcMoves:rcMoves,rcApply:rcApply,rcGoal:rcGoal,rcSolve:rcSolve,rcSafe:rcSafe};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RiverCrossingForgePure = EXPORTS; }
